import 'server-only'

import config from '@payload-config'
import { appAuth } from '@/lib/app-auth'
import { entitlementOf, hasCountryAccess } from '@/lib/billing'
import {
  roadmapStages,
  type DegreeLevel,
  type JourneyDTO,
  type OpportunityDTO,
  type PlanDTO,
  type RoadmapStage,
  type SessionUserDTO,
  type SettingsDTO,
  type StudentProfileDTO,
  type TaskDTO,
} from '@/lib/journey-contract'
import { getPayload } from 'payload'

/* eslint-disable @typescript-eslint/no-explicit-any */

/**
 * payload-types.ts is regenerated by the hosted dev environment, so the new collections and
 * fields are not in the generated types yet. These narrow local types keep the route handlers
 * honest without relying on them; every document is mapped to a DTO before leaving the server.
 */
export type Doc = Record<string, any> & { id: string | number }

type LooseArgs = Record<string, any>

export type LoosePayload = {
  find(args: LooseArgs): Promise<{ docs: Doc[]; totalDocs: number }>
  findByID(args: LooseArgs): Promise<Doc>
  create(args: LooseArgs): Promise<Doc>
  update(args: LooseArgs): Promise<Doc>
  delete(args: LooseArgs): Promise<Doc>
}

export type Session = NonNullable<Awaited<ReturnType<typeof appAuth.current>>>

export async function getPayloadServer(): Promise<LoosePayload> {
  const payload = await getPayload({ config })
  return payload as unknown as LoosePayload
}

/* ---------------------------------- responses ---------------------------------- */

export function jsonError(status: number, error: string, fieldErrors?: Record<string, string>) {
  return Response.json(fieldErrors ? { error, fieldErrors } : { error }, { status })
}

export const SERVER_ERROR_MESSAGE = 'Something went wrong. Please try again.'

/** Maps Payload errors to safe JSON responses without leaking internals. */
export function handleError(error: unknown) {
  const status =
    error && typeof error === 'object' && 'status' in error ? Number((error as any).status) : 0
  const name = error instanceof Error ? error.name : ''
  if (name === 'NotFound' || status === 404) return jsonError(404, 'Not found.')
  if (name === 'Forbidden' || status === 403) return jsonError(403, 'You do not have access to this.')
  if (name === 'ValidationError' || status === 400) {
    return jsonError(400, 'Check the values you entered and try again.')
  }
  console.error('[pathora-api]', error)
  return jsonError(500, SERVER_ERROR_MESSAGE)
}

/** Returns the signed-in session, or a ready-made 401 Response. */
export async function requireSession(): Promise<Session | Response> {
  const session = await appAuth.current()
  if (!session) return jsonError(401, 'Sign in required.')
  return session
}

/** Parses a JSON object body; returns null when the body is missing or not an object. */
export async function readJsonObject(request: Request): Promise<Record<string, unknown> | null> {
  try {
    const body: unknown = await request.json()
    if (!body || typeof body !== 'object' || Array.isArray(body)) return null
    return body as Record<string, unknown>
  } catch {
    return null
  }
}

export const badBody = () => jsonError(400, 'Invalid request body.')

/* ----------------------------------- helpers ----------------------------------- */

/** Payload `req.user` needs the `collection` marker that plain findByID docs lack. */
export const asReqUser = (doc: Doc) => ({ ...doc, collection: 'users' as const })

/**
 * Relationship values must match the DB id type: Postgres ids are numbers, but ids from URLs and
 * JSON bodies arrive as strings, and Payload rejects "2" as an invalid relationship.
 */
export function relId(value: string | number): string | number {
  return typeof value === 'string' && /^\d+$/.test(value) ? Number(value) : value
}

export function idOf(value: unknown): string | null {
  if (value === null || value === undefined || value === '') return null
  if (typeof value === 'object') {
    const id = (value as { id?: unknown }).id
    return id === null || id === undefined ? null : String(id)
  }
  return String(value)
}

const isoOrNull = (value: unknown): string | null => {
  if (typeof value !== 'string' && !(value instanceof Date)) return null
  const date = new Date(value)
  return Number.isNaN(date.getTime()) ? null : date.toISOString()
}

const strOrNull = (value: unknown): string | null =>
  typeof value === 'string' && value !== '' ? value : null

const numOrNull = (value: unknown): number | null =>
  typeof value === 'number' && Number.isFinite(value) ? value : null

const strArray = (value: unknown): string[] =>
  Array.isArray(value) ? value.filter((v): v is string => typeof v === 'string') : []

/* ----------------------------------- mappers ----------------------------------- */

/**
 * Maps an opportunity for a viewer. Without an active plan covering the listing's country the
 * detail fields are withheld here, on the server (`locked: true`); only card data is returned.
 */
export function toOpportunityDTO(doc: Doc, viewer?: Doc | null): OpportunityDTO {
  const locked = !hasCountryAccess(viewer, String(doc.country ?? ''))
  const image = doc.image && typeof doc.image === 'object' ? doc.image : null
  const requirements = doc.requirements && typeof doc.requirements === 'object' ? doc.requirements : {}
  return {
    id: String(doc.id),
    slug: String(doc.slug ?? ''),
    type: doc.type,
    title: String(doc.title ?? ''),
    institution: String(doc.institution ?? ''),
    country: String(doc.country ?? ''),
    city: strOrNull(doc.city),
    summary: locked ? null : strOrNull(doc.summary),
    studyFields: locked ? [] : strArray(doc.studyFields),
    degreeLevels: locked ? [] : (strArray(doc.degreeLevels) as DegreeLevel[]),
    fundingType: doc.fundingType ?? null,
    fundingSummary: strOrNull(doc.fundingSummary),
    deadline: isoOrNull(doc.deadline),
    deadlineNote: strOrNull(doc.deadlineNote),
    requirements: locked
      ? { minimumGpa: null, minimumIelts: null, notes: null }
      : {
          minimumGpa: numOrNull(requirements.minimumGpa),
          minimumIelts: numOrNull(requirements.minimumIelts),
          notes: strOrNull(requirements.notes),
        },
    imageUrl: image ? strOrNull(image.url) : null,
    imageAlt: image ? strOrNull(image.alt) : null,
    imageCredit: image ? strOrNull(image.credit) : null,
    sourceUrl: locked ? '' : String(doc.sourceUrl ?? ''),
    lastVerifiedAt: locked ? null : isoOrNull(doc.lastVerifiedAt),
    origin: doc.origin === 'ai' ? 'ai' : 'manual',
    sponsored: Boolean(doc.sponsored),
    locked,
  }
}

export function toTaskDTO(task: Record<string, any>): TaskDTO {
  return {
    id: String(task.id),
    title: String(task.title ?? ''),
    done: Boolean(task.done),
    dueDate: isoOrNull(task.dueDate),
  }
}

export function toPlanDTO(doc: Doc): PlanDTO {
  return {
    id: String(doc.id),
    opportunityId: idOf(doc.opportunity) ?? '',
    title: String(doc.title ?? ''),
    status: doc.status ?? 'preparing',
    targetDeadline: isoOrNull(doc.targetDeadline),
    tasks: Array.isArray(doc.tasks) ? doc.tasks.map(toTaskDTO) : [],
  }
}

export function toProfileDTO(user: Doc): StudentProfileDTO {
  const p = user.studentProfile && typeof user.studentProfile === 'object' ? user.studentProfile : {}
  const dob = isoOrNull(p.dateOfBirth)
  return {
    fullName: String(user.name ?? ''),
    preferredName: String(p.preferredName ?? ''),
    email: String(user.email ?? ''),
    phone: String(p.phone ?? ''),
    dateOfBirth: dob ? dob.slice(0, 10) : '',
    nationality: String(p.nationality ?? ''),
    currentCity: String(p.currentCity ?? ''),
    educationLevel: p.educationLevel ?? '',
    institution: String(p.institution ?? ''),
    gpa: numOrNull(p.gpa),
    graduationYear: numOrNull(p.graduationYear),
    desiredDegree: p.desiredDegree ?? '',
    preferredField: String(p.preferredField ?? ''),
    preferredDestination: String(p.preferredDestination ?? ''),
    englishTest: p.englishTest ?? '',
    englishScore: numOrNull(p.englishScore),
    annualBudgetThb: numOrNull(p.annualBudgetThb),
    fundingPreference: p.fundingPreference ?? '',
  }
}

export function toSettingsDTO(user: Doc): SettingsDTO {
  const s = user.settings && typeof user.settings === 'object' ? user.settings : {}
  return {
    language: s.language === 'th' ? 'th' : 'en',
    timezone: strOrNull(s.timezone) ?? 'Asia/Bangkok',
    emailUpdates: s.emailUpdates === undefined || s.emailUpdates === null ? true : Boolean(s.emailUpdates),
    deadlineReminders:
      s.deadlineReminders === undefined || s.deadlineReminders === null
        ? true
        : Boolean(s.deadlineReminders),
    profileVisibility: s.profileVisibility === 'buddies' ? 'buddies' : 'private',
  }
}

export function toSessionUserDTO(user: Doc): SessionUserDTO {
  return { id: String(user.id), email: String(user.email ?? ''), name: String(user.name ?? '') }
}

export function computeProfileCompletion(profile: StudentProfileDTO): number {
  const values = Object.values(profile)
  const filled = values.filter((v) => (typeof v === 'number' ? Number.isFinite(v) : v !== null && v !== '')).length
  return Math.round((filled / values.length) * 100)
}

export const currentCompletedStages = (user: Doc): RoadmapStage[] =>
  strArray(user.roadmap?.completedStages).filter((s): s is RoadmapStage =>
    (roadmapStages as string[]).includes(s),
  )

/* ------------------------------- data loading --------------------------------- */

export async function listSavedIds(payload: LoosePayload, user: Doc): Promise<string[]> {
  const result = await payload.find({
    collection: 'saved-opportunities',
    where: { owner: { equals: user.id } },
    limit: 500,
    depth: 0,
    pagination: false,
    overrideAccess: false,
    user: asReqUser(user),
  })
  return result.docs.map((d) => idOf(d.opportunity)).filter((id): id is string => Boolean(id))
}

export async function listPlans(payload: LoosePayload, user: Doc): Promise<Doc[]> {
  const result = await payload.find({
    collection: 'application-plans',
    where: { owner: { equals: user.id } },
    limit: 500,
    depth: 0,
    sort: 'createdAt',
    pagination: false,
    overrideAccess: false,
    user: asReqUser(user),
  })
  return result.docs
}

export async function buildJourney(user: Doc): Promise<JourneyDTO> {
  const payload = await getPayloadServer()
  const [saved, planDocs] = await Promise.all([listSavedIds(payload, user), listPlans(payload, user)])
  const plans = planDocs.map(toPlanDTO)
  const profile = toProfileDTO(user)
  const activePlanId = idOf(user.roadmap?.activePlan)
  return {
    user: toSessionUserDTO(user),
    profile,
    settings: toSettingsDTO(user),
    roadmap: {
      activePlanId: activePlanId && plans.some((p) => p.id === activePlanId) ? activePlanId : null,
      completedStages: currentCompletedStages(user),
    },
    saved,
    plans,
    localImportDone: Boolean(user.localImportDone),
    entitlement: entitlementOf(user),
    profileCompletion: computeProfileCompletion(profile),
  }
}

/** Fresh copy of the signed-in user's own document (access-checked). */
export async function loadUserDoc(payload: LoosePayload, session: Session): Promise<Doc> {
  return payload.findByID({
    collection: 'users',
    id: session.user.id,
    depth: 0,
    overrideAccess: false,
    user: session.user,
  })
}

/** Responds 402 when the user's plan does not cover the opportunity's country. */
export function planRequired(country: string) {
  return Response.json(
    {
      error: `Unlock ${country || 'this country'} with a plan that covers it to use this.`,
      code: 'plan_required',
    },
    { status: 402 },
  )
}

/** Opportunity readable by the viewer, or null (missing, hidden, or malformed id). */
export async function getReadableOpportunity(
  payload: LoosePayload,
  id: string,
  user: Session['user'] | undefined,
  depth = 0,
): Promise<Doc | null> {
  try {
    return await payload.findByID({
      collection: 'opportunities',
      id,
      depth,
      overrideAccess: false,
      user,
    })
  } catch {
    return null
  }
}

/** Plan owned by the user, or null. */
export async function getOwnedPlan(
  payload: LoosePayload,
  id: string,
  user: Session['user'],
): Promise<Doc | null> {
  try {
    return await payload.findByID({
      collection: 'application-plans',
      id,
      depth: 0,
      overrideAccess: false,
      user,
    })
  } catch {
    return null
  }
}

/** Existing task rows in the shape needed to write the array back (ids preserved). */
export const rawTasks = (plan: Doc): Array<Record<string, any>> =>
  (Array.isArray(plan.tasks) ? plan.tasks : []).map((t: Record<string, any>) => ({
    id: t.id,
    title: t.title,
    done: Boolean(t.done),
    dueDate: t.dueDate ?? null,
  }))

export async function writePlanTasks(
  payload: LoosePayload,
  plan: Doc,
  tasks: Array<Record<string, any>>,
  user: Session['user'],
): Promise<PlanDTO> {
  const updated = await payload.update({
    collection: 'application-plans',
    id: plan.id,
    data: { tasks },
    depth: 0,
    overrideAccess: false,
    user,
  })
  return toPlanDTO(updated)
}

/* -------------------------------- validation ---------------------------------- */

export type FieldErrors = Record<string, string>
export type CleanResult<T> = { data: T } | { fieldErrors: FieldErrors }

type Spec =
  | { kind: 'text'; max: number; required?: boolean }
  | { kind: 'select'; options: readonly string[] }
  | { kind: 'number'; min?: number; max?: number; int?: boolean }
  | { kind: 'date' }
  | { kind: 'boolean' }

const hasOwn = (obj: object, key: string) => Object.prototype.hasOwnProperty.call(obj, key)

/** Validates a date input: '' / null clear it; otherwise YYYY-MM-DD or ISO. */
export function cleanDate(value: unknown): { ok: true; value: string | null } | { ok: false } {
  if (value === null || value === undefined || value === '') return { ok: true, value: null }
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}(T[\d:.]+(Z|[+-]\d{2}:?\d{2})?)?$/.test(value.trim())) {
    return { ok: false }
  }
  const date = new Date(value.trim())
  if (Number.isNaN(date.getTime())) return { ok: false }
  return { ok: true, value: date.toISOString() }
}

/** Validates a task title: trimmed, 1-200 characters. */
export function cleanTaskTitle(value: unknown): string | null {
  if (typeof value !== 'string') return null
  const title = value.trim()
  return title.length >= 1 && title.length <= 200 ? title : null
}

function cleanFields(
  input: Record<string, unknown>,
  specs: Record<string, Spec>,
): { values: Record<string, unknown>; fieldErrors: FieldErrors } {
  const values: Record<string, unknown> = {}
  const fieldErrors: FieldErrors = {}

  for (const [key, spec] of Object.entries(specs)) {
    if (!hasOwn(input, key)) continue
    const raw = input[key]

    switch (spec.kind) {
      case 'text': {
        if (raw === null || raw === undefined) {
          if (spec.required) fieldErrors[key] = 'This field is required.'
          else values[key] = null
          break
        }
        if (typeof raw !== 'string') {
          fieldErrors[key] = 'Enter text.'
          break
        }
        const text = raw.trim()
        if (text.length > spec.max) fieldErrors[key] = `Use ${spec.max} characters or fewer.`
        else if (text === '' && spec.required) fieldErrors[key] = 'This field is required.'
        else values[key] = text === '' ? null : text
        break
      }
      case 'select': {
        if (raw === null || raw === undefined || raw === '') values[key] = null
        else if (typeof raw === 'string' && spec.options.includes(raw)) values[key] = raw
        else fieldErrors[key] = 'Choose a valid option.'
        break
      }
      case 'number': {
        if (raw === null || raw === undefined || (typeof raw === 'string' && raw.trim() === '')) {
          values[key] = null
          break
        }
        const num = typeof raw === 'number' ? raw : typeof raw === 'string' ? Number(raw.trim()) : NaN
        const outOfRange =
          (spec.min !== undefined && num < spec.min) || (spec.max !== undefined && num > spec.max)
        if (!Number.isFinite(num) || outOfRange || (spec.int && !Number.isInteger(num))) {
          const range =
            spec.min !== undefined && spec.max !== undefined
              ? ` between ${spec.min} and ${spec.max}`
              : spec.min !== undefined
                ? ` of ${spec.min} or more`
                : ''
          fieldErrors[key] = `Enter a${spec.int ? ' whole' : ''} number${range}.`
        } else {
          values[key] = num
        }
        break
      }
      case 'date': {
        const result = cleanDate(raw)
        if (result.ok) values[key] = result.value
        else fieldErrors[key] = 'Enter a valid date (YYYY-MM-DD).'
        break
      }
      case 'boolean': {
        if (typeof raw === 'boolean') values[key] = raw
        else fieldErrors[key] = 'Must be true or false.'
        break
      }
    }
  }

  return { values, fieldErrors }
}

const profileSpecs: Record<string, Spec> = {
  fullName: { kind: 'text', max: 120 },
  preferredName: { kind: 'text', max: 80 },
  phone: { kind: 'text', max: 40 },
  dateOfBirth: { kind: 'date' },
  nationality: { kind: 'text', max: 80 },
  currentCity: { kind: 'text', max: 120 },
  educationLevel: { kind: 'select', options: ['high-school', 'bachelor', 'master'] },
  institution: { kind: 'text', max: 160 },
  gpa: { kind: 'number', min: 0, max: 4 },
  graduationYear: { kind: 'number', min: 1950, max: 2100, int: true },
  desiredDegree: { kind: 'select', options: ['bachelor', 'master', 'phd'] },
  preferredField: { kind: 'text', max: 120 },
  preferredDestination: { kind: 'text', max: 80 },
  englishTest: { kind: 'select', options: ['ielts', 'toefl', 'duolingo'] },
  englishScore: { kind: 'number', min: 0, max: 160 },
  annualBudgetThb: { kind: 'number', min: 0 },
  fundingPreference: { kind: 'select', options: ['full', 'partial', 'self'] },
}

export type ProfilePatch = { name?: string; studentProfile: Record<string, unknown> }

/** `email` is read-only here and ignored; `fullName` maps to the user `name`. */
export function cleanProfilePatch(body: unknown): CleanResult<ProfilePatch> {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return { fieldErrors: { profile: 'Invalid profile.' } }
  }
  const { values, fieldErrors } = cleanFields(body as Record<string, unknown>, profileSpecs)
  if (Object.keys(fieldErrors).length) return { fieldErrors }

  const { fullName, ...rest } = values
  const data: ProfilePatch = { studentProfile: rest }
  if ('fullName' in values) data.name = typeof fullName === 'string' ? fullName : ''
  return { data }
}

const settingsSpecs: Record<string, Spec> = {
  language: { kind: 'select', options: ['en', 'th'] },
  timezone: { kind: 'text', max: 60, required: true },
  emailUpdates: { kind: 'boolean' },
  deadlineReminders: { kind: 'boolean' },
  profileVisibility: { kind: 'select', options: ['private', 'buddies'] },
}

export function cleanSettingsPatch(body: unknown): CleanResult<Record<string, unknown>> {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return { fieldErrors: { settings: 'Invalid settings.' } }
  }
  const { values, fieldErrors } = cleanFields(body as Record<string, unknown>, settingsSpecs)
  if (Object.keys(fieldErrors).length) return { fieldErrors }
  // Selects have defaults; never write null over them.
  for (const key of ['language', 'profileVisibility']) {
    if (key in values && values[key] === null) delete values[key]
  }
  return { data: values }
}

export type RoadmapPatch = { activePlanId?: string | null; completedStages?: RoadmapStage[] }

/** Shape-only validation; the route verifies that activePlanId belongs to the user. */
export function cleanRoadmapPatch(body: unknown): CleanResult<RoadmapPatch> {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return { fieldErrors: { roadmap: 'Invalid roadmap.' } }
  }
  const input = body as Record<string, unknown>
  const data: RoadmapPatch = {}
  const fieldErrors: FieldErrors = {}

  if (hasOwn(input, 'activePlanId')) {
    const raw = input.activePlanId
    if (raw === null || raw === '') data.activePlanId = null
    else if (typeof raw === 'string' && raw.length <= 100) data.activePlanId = raw
    else fieldErrors.activePlanId = 'Choose a valid plan.'
  }

  if (hasOwn(input, 'completedStages')) {
    const raw = input.completedStages
    if (
      Array.isArray(raw) &&
      raw.length <= 20 &&
      raw.every((s) => typeof s === 'string' && (roadmapStages as string[]).includes(s))
    ) {
      data.completedStages = roadmapStages.filter((s) => (raw as string[]).includes(s))
    } else {
      fieldErrors.completedStages = 'Choose valid stages.'
    }
  }

  return Object.keys(fieldErrors).length ? { fieldErrors } : { data }
}
